WITH cleaned AS (SELECT id, order_id, carrier, delivered_date, cost, status, DATEDIFF(CURRENT_DATE(), delivered_date) AS days_since_delivered_date, ROUND(cost * 1.07, 2) AS adjusted_cost, COALESCE(carrier, 'UNKNOWN') AS carrier_clean FROM shipments WHERE cost <= 84) SELECT o.channel, a.carrier, COUNT(*) AS rows_total, ROUND(AVG(a.adjusted_cost), 2) AS avg_adjusted_cost, ROUND(AVG(a.cost), 2) AS avg_cost, GROUPING_ID() AS gid FROM cleaned a JOIN orders o ON a.order_id = o.id GROUP BY CUBE (o.channel, a.carrier);
